// Node.js არის JavaScript-ის შესრულების გარემო, რომელიც მუშაობს ბრაუზერს გარეთ.
// მისი დახმარებით შეგვიძლია JavaScript-ი გამოვიყენოთ სერვერზე, დავწეროთ backend,
// ავამუშავოთ სკრიპტები და ა.შ.

// --- რა არის package.json ---
// package.json არის პროექტის კონფიგურაციული ფაილი, რომელიც ინახავს ინფორმაციას
// პროექტზე (სახელი, ვერსია, ავტორი, ლიცენზია) და ასევე ჩამოთვლის, 
// თუ რა პაკეტებია საჭირო პროექტის მუშაობისთვის (dependencies).

// --- რომელი package დავაყენეთ ---
// დავაყენეთ "lodash". ეს არის JavaScript utility ბიბლიოთეკა,
// რომელიც გვეხმარება მასივების, ობიექტების, სტრინგების და სხვა მონაცემთა სტრუქტურების
// მარტივად დამუშავებაში. ხშირად გამოიყენება დიდი პროექტებში,
// რომ თავიდან ავირიდოთ იგივე კოდის ხელახლა წერა.

const _ = require("lodash");

const numbers = [10, 5, 8, 130, 44];

console.log("მაქსიმუმი:", _.max(numbers));
console.log("მინიმუმი:", _.min(numbers));
console.log("Shuffle:", _.shuffle(numbers));
console.log("Sorted Asc:", _.sortBy(numbers)); 
